interface=sys.argv[2]
if sys.argv[1]=='down':
 subprocess.run(['ip','tunnel','del',interface],check=False)
else:
 run(['ip','tunnel','add',interface,'mode',sys.argv[3],'local',sys.argv[4],'remote',sys.argv[5],'ttl','64'])
 try:
